# Writes fft_tables.h: a quarter-wave cosine table (the twiddles and the Hann window are built
# from it in fft.c) and a log2 table.
import math, os
N = 256
tw = [(round(math.cos(2 * math.pi * k / N) * 32767), round(-math.sin(2 * math.pi * k / N) * 32767)) for k in range(N // 2)]
win = [round((0.5 - 0.5 * math.cos(2 * math.pi * n / N)) * 32767) for n in range(N // 2)]
with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'fft_tables.h'), 'w') as f:
    f.write('// Generated by gen_tables.py.\n')
    qc = [round(math.cos(2 * math.pi * k / N) * 32767) for k in range(65)]
    f.write('// cos(2 pi k / 256), k = 0..64, Q15: the full twiddle table is built from it in RAM (fft.c)\n')
    f.write('static const short QC[65] = {\n  ' + ', '.join(map(str, qc)) + '\n};\n')
    lg = [round(math.log2(1 + i / 32) * 256) for i in range(32)]
    f.write('// log2(1 + i/32) in Q8\nstatic const unsigned char LOG2F[32] = {\n  ' + ', '.join(map(str, lg)) + '\n};\n')
